import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.DDY-poMm.js";const p=JSON.parse('{"title":"Trading Products","description":"","frontmatter":{},"headers":[],"relativePath":"guide/trading.md","filePath":"guide/trading.md","lastUpdated":1790683574000}'),i={name:"guide/trading.md"};function n(s,e,l,d,c,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="trading-products" tabindex="-1">Trading Products <a class="header-anchor" href="#trading-products" aria-label="Permalink to &quot;Trading Products&quot;">​</a></h1><p>This page explains <strong>what each trading product is and who it is for</strong>. Whether each is open to users is controlled by &quot;Basic Configuration → Product configuration&quot;.</p><h2 id="spot-coin-to-coin" tabindex="-1">Spot (coin-to-coin) <a class="header-anchor" href="#spot-coin-to-coin" aria-label="Permalink to &quot;Spot (coin-to-coin)&quot;">​</a></h2><p>The most basic form of trading: buying or selling one asset with another.</p><ul><li>Limit and market orders</li><li>Trading pairs and fees are configured in &quot;Coin Management&quot; in the admin console</li><li>For: users with a clear intent to buy or sell</li></ul><h3 id="manual-forced-fill-operator-feature" tabindex="-1">Manual forced fill (operator feature) <a class="header-anchor" href="#manual-forced-fill-operator-feature" aria-label="Permalink to &quot;Manual forced fill (operator feature)&quot;">​</a></h3><p>A limit order only fills when the market reaches the order price; if the market never gets there, the order stays open. Operators can execute a &quot;forced fill&quot; on <strong>pending</strong> limit orders from the &quot;Spot Orders&quot; list in the admin console.</p><ul><li>Fills the full order at its <strong>order price</strong>, regardless of the current market</li><li>Fees are charged as usual, and the trade record the user sees is identical to a normal fill</li><li>Only available for orders in &quot;Pending&quot; status; filled or cancelled orders do not show the button</li><li>Every action is recorded in the &quot;Operation Log&quot;, tracing who did it and when</li><li>TradFi instruments such as forex, gold, stocks and indices share the same order mechanism as spot, so this applies to them too</li></ul><div class="warning custom-block"><p class="custom-block-title">This action cannot be undone</p><p>A forced fill immediately debits, credits and writes ledger entries, and cannot be rolled back. Check the order details first. It requires the &quot;Forced fill&quot; permission, which can be granted per role in &quot;Role Management&quot;.</p></div><h2 id="instant-swap" tabindex="-1">Instant swap <a class="header-anchor" href="#instant-swap" aria-label="Permalink to &quot;Instant swap&quot;">​</a></h2><p><strong>Convert directly</strong> between two assets at the current price, without placing an order and waiting for a fill.</p><ul><li>Simple, done in one step</li><li>For: users who just want to swap coins and don&#39;t care about order prices</li></ul><h2 id="seconds-contracts" tabindex="-1">Seconds contracts <a class="header-anchor" href="#seconds-contracts" aria-label="Permalink to &quot;Seconds contracts&quot;">​</a></h2><p>Predict whether the price will go up or down <strong>within a short period</strong>, settled on the outcome at expiry.</p><ul><li>Short periods, simple rules</li><li>Periods and settlement parameters are configurable in the admin console</li><li>For: users who prefer lightweight products</li></ul><h2 id="usdt-margined-perpetuals" tabindex="-1">USDT-margined perpetuals <a class="header-anchor" href="#usdt-margined-perpetuals" aria-label="Permalink to &quot;USDT-margined perpetuals&quot;">​</a></h2><p>Leveraged two-way trading — go long or short.</p><ul><li>Selectable leverage</li><li>Take-profit and stop-loss</li><li><strong>Forced liquidation</strong> when margin is insufficient</li><li>For: experienced traders</li></ul><div class="tip custom-block"><p class="custom-block-title">Predictable settlement</p><p>Contract liquidation has been specifically hardened: if the market data feed is interrupted, stale quotes are detected and rejected, and the system pauses liquidation and conditional-order triggers for that instrument until data recovers, then re-evaluates at the real market price. A position is settled exactly once — no duplicate debits or credits.</p></div><h2 id="tradfi-instruments" tabindex="-1">TradFi instruments <a class="header-anchor" href="#tradfi-instruments" aria-label="Permalink to &quot;TradFi instruments&quot;">​</a></h2><p>Beyond digital assets, the platform offers market data and trading for <strong>forex, commodities, stocks, indices, Hong Kong equities</strong> and other traditional instruments.</p><ul><li>Market data comes from third-party sources configured in the admin console</li><li>Instruments priced in other currencies (e.g. HK or China A-shares) are converted using exchange rates configured in the admin console</li><li><strong>Market hours</strong>: traditional markets open and close; trading is unavailable while markets are closed, and the system shows a notice</li></ul><div class="danger custom-block"><p class="custom-block-title">Exchange rate configuration</p><p>A wrong exchange rate makes every instrument priced in that currency execute at a wrongly scaled price. This is a <strong>super-admin-only</strong> setting; change it with extra care.</p></div><h2 id="copy-trading" tabindex="-1">Copy trading <a class="header-anchor" href="#copy-trading" aria-label="Permalink to &quot;Copy trading&quot;">​</a></h2><p>See <a href="/CoinExchange/guide/follow">Copy Trading</a>.</p><h2 id="platform-tokens-market-making" tabindex="-1">Platform tokens &amp; market making <a class="header-anchor" href="#platform-tokens-market-making" aria-label="Permalink to &quot;Platform tokens &amp; market making&quot;">​</a></h2><p>The platform can issue its own tokens (&quot;Platform Tokens&quot; in the admin console) and assign them to designated market maker accounts (see <a href="/CoinExchange/guide/market-maker">Market Maker Portal</a>); in coin configuration, a platform token can also serve as a <strong>fee-deduction token</strong>, offsetting spot fees at a discount rate.</p><h2 id="token-subscription-ipo" tabindex="-1">Token subscription (IPO) <a class="header-anchor" href="#token-subscription-ipo" aria-label="Permalink to &quot;Token subscription (IPO)&quot;">​</a></h2><p>A new-coin subscription product. Projects move through the stages &quot;Preparing → Subscription → Approval → In progress → Issued&quot; in the admin console.</p><div class="warning custom-block"><p class="custom-block-title">Configuration reminder</p><p>When creating a subscription project, <strong>&quot;Purchase limit&quot; must be filled in</strong>; leaving it empty may cause order errors on the user side.</p></div>',30)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
